import java.time.LocalDate; import com.evolveum.midpoint.xml.ns._public.common.common_3.ActivationStatusType;
if (terminationDate == null) return null;
// ¿Ceso de verdad? Solo true con fecha valida YYYY-MM-DD y ya cumplida.
// Dato ilegible o fecha futura -> ceased=false -> NO se desactiva (fail-safe).
def ceased = false;
def v = basic.stringify(terminationDate);
if (v ==~ /^\d{4}-\d{2}-\d{2}$/) {
    try { ceased = !LocalDate.parse(v).isAfter(LocalDate.now()) } catch (Exception e) { log.warn("leaver: terminationDate no parseable '{}' en {} -> no se desactiva", v, focus?.name) }
} else {
    log.warn("leaver: terminationDate con formato inesperado '{}' en {} -> no se desactiva", v, focus?.name)
}
// ¿Le queda ALGUN vinculo vivo? 'sin dato' y 'vacio' NO cuentan como vivo.
def liveOf = { it != null && basic.stringify(it).trim() != '' };
def anyLive = liveOf(worker) || liveOf(student) || liveOf(alum);
// ISO 24760: ceso y sin ningun vinculo -> suspended. Con vinculo vivo -> su
// identidad persiste por otra IIA -> ENABLED.
return (ceased && !anyLive) ? ActivationStatusType.DISABLED : ActivationStatusType.ENABLED

def liveOf = { it != null && basic.stringify(it).trim() != '' }
def anyLive = liveOf(worker) || liveOf(student) || liveOf(alum)
return anyLive && adminStatus != null && adminStatus.toString().equalsIgnoreCase('disabled')

// RANGO (no condition): retirable el DISABLED actual si hay un vinculo VIVO (item + cuenta de su IIA).
if (input == null || !basic.stringify(input).trim().equalsIgnoreCase('disabled')) return false
def CANARIO = []  // lista de canario: NO en el repo publico (PII); vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
def NS = 'urn:sciback:midpoint:person'
def live = { String item, String res -> def v = basic.getExtensionPropertyValue(focus, NS, item); v != null && basic.stringify(v).trim() != '' && midpoint.hasLinkedAccount(res) }
try { def ok = live('liveAffiliationWorker', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e21') || live('liveAffiliationStudent', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22') || live('liveAffiliationAlum', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e23'); if (ok) log.warn('ACTv2: limpia DISABLED de {} (vinculo vivo)', focus?.name); return ok } catch (Exception e) { log.warn('ACTv2: fallo en {}: {} -> no se limpia', focus?.name, e.message); return false }

// RANGO (no condition): retirable el valor actual si NO hay cuenta viva de su IIA en el contexto.
if (input == null || basic.stringify(input).trim() == '') return false
def CANARIO = []  // lista de canario: NO en el repo publico (PII); vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22'); if (gone) log.warn('R1v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R1v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }

// RANGO (no condition): retirable el valor actual si NO hay cuenta viva de su IIA en el contexto.
if (input == null || basic.stringify(input).trim() == '') return false
def CANARIO = []  // lista de canario: NO en el repo publico (PII); vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e23'); if (gone) log.warn('R2v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R2v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }

// RANGO (no condition): retirable el valor actual si NO hay cuenta viva de su IIA en el contexto.
if (input == null || basic.stringify(input).trim() == '') return false
def CANARIO = []  // lista de canario: NO en el repo publico (PII); vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e21'); if (gone) log.warn('R3v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R3v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }
